local function endsWith(p1, p2, p3) -- line: 2
    local v1 = p2:len()

    if v1 == 0 then
        return true
    end

    local v2 = p1:len()

    p3 = p3 or v2

    if not (v2 < p3) then
        v2 = p3
    end

    if v2 < 1 then
        return false
    end

    local v4 = v2 - v1 + 1

    return p1:find(p2, v4, true) == v4
end

return endsWith
